function startRoom()
{
   SHELL.addListener(SHELL.PLAYER_MOVE,handleUpdatePlayer);
   SHELL.addListener(SHELL.PLAYER_FRAME,handleUpdatePlayer);
   SHELL.addListener(SHELL.UPDATE_PLAYER,handleUpdatePlayer);
   SHELL.addListener(SHELL.ROOM_DESTROYED,handleRoomDestroyed);
}
function fill()
{
   if(background_mc.flowPipe_mc._currentframe == 1 and bucketFill == 2)
   {
      background_mc.flowPipe_mc.gotoAndStop(2);
   }
   else if(background_mc.flowPipe_mc._currentframe != flowpipe_FLOWING_FRAME)
   {
      background_mc.flowPipe_mc.gotoAndStop(bucketFill);
   }
   if(background_mc.flowPipe_mc._currentframe == flowpipe_FLOWING_FRAME)
   {
      bucketFill += 1;
   }
}
function empty()
{
   bucketFill -= 1;
   if(bucketFill < 1)
   {
      bucketFill = 1;
   }
   if(bucketFill == 5)
   {
      background_mc.flowPipe_mc.flow_mc.gotoAndStop("end");
      bucketFill = 1;
   }
   else if(bucketFill < 5)
   {
      background_mc.flowPipe_mc.gotoAndStop(bucketFill);
   }
}
function handleThrow(mc)
{
   if(mc._x > 295 && mc._x < 372)
   {
      if(mc._y > 76 && mc._y < 105)
      {
         background_mc.bucket_mc.gotoAndPlay(2);
         background_mc.bucketBack_mc.gotoAndPlay(2);
         bucketFill += 1;
         if(bucketFill > 8)
         {
            bucketFill = 8;
         }
         fill();
         mc._visible = false;
      }
   }
}
function checkGrowth()
{
   i = 0;
   while(i < plantArray.length)
   {
      if(plantArray[i]._currentframe != plant_HARVEST_FRAME)
      {
         if(plantGrowthArray[i] == plant_GROWTH_1)
         {
            plantArray[i].play();
            plantArray[i].healthyPlant.play();
            plantGrowthArray[i] += 1;
         }
         else if(plantGrowthArray[i] == plant_GROWTH_2)
         {
            plantArray[i].play();
            plantArray[i].healthyPlant.play();
            plantGrowthArray[i] += 1;
         }
         else if(plantGrowthArray[i] == plant_GROWTH_3)
         {
            plantArray[i].play();
            plantArray[i].healthyPlant.play();
            plantGrowthArray[i] += 1;
         }
         else if(plantGrowthArray[i] >= plant_GROWTH_4)
         {
            plantArray[i].play();
            plantArray[i].healthyPlant.play();
            plantGrowthArray[i] = 0;
            harvestFill += 1;
            harvestShed_mc.barrel_mc.gotoAndPlay(1);
         }
      }
      i++;
   }
}
function gardening()
{
   i = 0;
   var _loc1_;
   while(i < plotTendedArray.length)
   {
      if(plotTendedArray[i] == true)
      {
         trace("PLAYER_LIST" + PLAYER_LIST);
         if(plantArray[i]._currentframe != plant_HARVEST_FRAME)
         {
            trace(plantArray[i] + " is growing");
            plantWitherArray[i] = 0;
            plantGrowthArray[i] += 1;
         }
         a = 0;
         while(a < PLAYER_LIST.length)
         {
            _loc1_ = new Array();
            _loc1_[a] = SHELL.getPlayerObjectById(PLAYER_LIST[a].player_id);
            if(_loc1_[a].body == FIREMAN_OUTFIT[0] || _loc1_[a].body == FIREMAN_OUTFIT[1])
            {
               if(digAreaArray[i].hitTest(_loc1_[a].x + 50,_loc1_[a].y))
               {
                  if(_loc1_[a].frame == DANCE_FRAME && secretFrame != _loc1_[a].frame)
                  {
                     trace("plot tended");
                     stillTended += 1;
                  }
               }
            }
            else if(_loc1_[a].body == WATER_PACK)
            {
               if(digAreaArray[i].hitTest(_loc1_[a].x - 50,_loc1_[a].y))
               {
                  if(_loc1_[a].frame == DANCE_FRAME && secretFrame != _loc1_[a].frame)
                  {
                     trace("plot tended");
                     stillTended += 1;
                  }
               }
            }
            else if(digAreaArray[i].hitTest(_loc1_[a].x,_loc1_[a].y))
            {
               if(_loc1_[a].frame == DANCE_FRAME && secretFrame != _loc1_[a].frame)
               {
                  if(_loc1_[a].head == HARD_HAT_ID[0] || _loc1_[a].head == HARD_HAT_ID[1] || _loc1_[a].head == HARD_HAT_ID[2] || _loc1_[a].head == HARD_HAT_ID[3] || _loc1_[a].head == HARD_HAT_ID[4] || _loc1_[a].head == HARD_HAT_ID[5] || _loc1_[a].head == GARDENING_HAT || _loc1_[a].body == FIREMAN_OUTFIT || _loc1_[a].neck == WATER_PACK)
                  {
                     trace("plot tended");
                     stillTended += 1;
                  }
               }
            }
            a++;
         }
         if(stillTended == 0)
         {
            trace("plot abandoned");
            plotTendedArray[i] = false;
         }
         stillTended = 0;
      }
      i++;
   }
}
function sprinklers()
{
   if(sprayPipe_mc._currentframe != 1)
   {
      i = 0;
      while(i < plantArray.length)
      {
         if(plantArray[i]._currentframe != plant_HARVEST_FRAME)
         {
            plantWitherArray[i] = 0;
            plantGrowthArray[i] += 1;
         }
         i++;
      }
   }
}
function checkWither()
{
   if(sprayPipe_mc._currentframe != 2)
   {
      i = 0;
      while(i < plantArray.length)
      {
         if(plantArray[i]._currentframe != plant_HARVEST_FRAME)
         {
            if(plantArray[i]._currentframe != 1)
            {
               if(plantWitherArray[i] == TEN_SECONDS)
               {
                  plantWitherArray[i] += 1;
                  plantArray[i].healthyPlant.healthyPlant.gotoAndPlay(2);
               }
               else if(plantWitherArray[i] >= 40)
               {
                  plantArray[i].gotoAndStop("harvest");
                  plantArray[i].healthyPlant.gotoAndStop("end");
                  plantWitherArray[i] = 0;
                  plantGrowthArray[i] = 0;
               }
               else
               {
                  plantWitherArray[i] += 1;
               }
            }
         }
         i++;
      }
   }
}
function harvest()
{
   i = 0;
   while(i < plantArray.length)
   {
      if(plantArray[i]._currentframe == plant_HARVEST_FRAME)
      {
         plantHarvestArray[i] += 1;
         if(plantHarvestArray[i] >= TEN_SECONDS)
         {
            plantArray[i].gotoAndStop(1);
            plantHarvestArray[i] = 0;
         }
      }
      i++;
   }
   if(harvestFill >= 20 and harvestShed_mc._currentframe < 11)
   {
      harvestShed_mc.play();
   }
   else if(harvestFill >= 40 and harvestShed_mc._currentframe >= 11 and harvestShed_mc._currentframe < 21)
   {
      harvestShed_mc.play();
   }
   else if(harvestFill >= 60 and harvestShed_mc._currentframe >= 21 and harvestShed_mc._currentframe < 31)
   {
      harvestShed_mc.play();
   }
}
function handleUpdatePlayer(event)
{
   var _loc1_ = SHELL.getPlayerObjectById(event.player_id);
   var _loc2_ = SHELL.getSecretFrame(_loc1_.player_id,_loc1_.frame);
   i = 0;
   while(i < digAreaArray.length)
   {
      if(_loc1_.body == FIREMAN_OUTFIT[0] || _loc1_.body == FIREMAN_OUTFIT[1])
      {
         if(digAreaArray[i].hitTest(_loc1_.x + 50,_loc1_.y))
         {
            trace("hit");
            if(_loc1_.frame == DANCE_FRAME && _loc2_ != _loc1_.frame)
            {
               trace("Detected Secret Dance Frame");
               plotTendedArray[i] = true;
            }
         }
      }
      else if(_loc1_.body == WATER_PACK)
      {
         if(digAreaArray[i].hitTest(_loc1_.x - 50,_loc1_.y))
         {
            trace("hit");
            if(_loc1_.frame == DANCE_FRAME && _loc2_ != _loc1_.frame)
            {
               trace("Detected Secret Dance Frame");
               plotTendedArray[i] = true;
            }
         }
      }
      else if(digAreaArray[i].hitTest(_loc1_.x,_loc1_.y))
      {
         trace("hit");
         if(_loc1_.frame == DANCE_FRAME && _loc2_ != _loc1_.frame)
         {
            trace("Detected Secret Dance Frame");
            if(_loc1_.head == HARD_HAT_ID[0] || _loc1_.head == HARD_HAT_ID[1] || _loc1_.head == HARD_HAT_ID[2] || _loc1_.head == HARD_HAT_ID[3] || _loc1_.head == HARD_HAT_ID[4] || _loc1_.head == HARD_HAT_ID[5] || _loc1_.head == GARDENING_HAT || _loc1_.body == FIREMAN_OUTFIT || _loc1_.neck == WATER_PACK)
            {
               plotTendedArray[i] = true;
            }
         }
      }
      i++;
   }
}
function handleRoomDestroyed()
{
   SHELL.removeListener(SHELL.PLAYER_MOVE,handleUpdatePlayer);
   SHELL.removeListener(SHELL.PLAYER_FRAME,handleUpdatePlayer);
   SHELL.removeListener(SHELL.UPDATE_PLAYER,handleUpdatePlayer);
   SHELL.removeListener(SHELL.ROOM_DESTROYED,handleRoomDestroyed);
   clearInterval(emptyID);
   clearInterval(checkWitherID);
   clearInterval(checkGrowthID);
   clearInterval(harvestID);
   clearInterval(sprinklersID);
   clearInterval(gardningID);
}
